'use strict';
let T,I,E,G,L,A;const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return(c==='x'?r:(r&3|8)).toString(16)});
const safeRead=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};let state={horizon:1,chapter:1,view:'overview',...safeRead('wp-atlas-state',{})};let notes=safeRead('wp-atlas-notes',[]);let filters={character:'',place:'',theme:'',family:'',thread:'',group:'thread',order:'narrative',mode:'',query:'',comparison:'',graph:'relations',mapPlace:'',region:'europe'};let focusParagraph=null,lastFocus=null;
const navs=[['overview','◈','Overview'],['read','▤','The text'],['characters','♙','Characters'],['connections','⌘','Connections'],['timeline','⌁','Timelines'],['atlas','◎','Atlas'],['knowledge','◇','Who knows?'],['query','⌕','Query lab'],['notebook','✎','Notebook']];
const save=()=>{try{localStorage.setItem('wp-atlas-state',JSON.stringify(state));localStorage.setItem('wp-atlas-notes',JSON.stringify(notes))}catch{toast('Browser storage is unavailable. Export notes to keep them.')}};
const chapter=id=>T.chapters[id-1];const chLabel=id=>{const c=chapter(id);return c?(c.book<16?`Book ${c.book}`:`Epilogue ${c.book-15}`)+` · ${c.roman}`:''};
const character=id=>I.characters.find(c=>c.id===id);const name=id=>character(id)?.name||id||'Reader';const placeName=id=>I.places.find(p=>p.id===id)?.name||'Unspecified';
const unlockedChars=()=>I.characters.filter(c=>c.first<=state.horizon);const unlockedPlaces=()=>I.places.filter(p=>p.first<=state.horizon);const visibleEvents=()=>E.events.filter(e=>e.chapter<=state.horizon);const visibleKnowledge=()=>E.knowledge.filter(e=>e.chapter<=state.horizon);const visibleRelations=()=>E.relations.filter(e=>e.chapter<=state.horizon&&character(e.from)?.first<=state.horizon&&character(e.to)?.first<=state.horizon);const mentions=(c)=>c.hits.filter(h=>h.chapter<=state.horizon);
const initials=n=>n.split(' ').filter(x=>!['Prince','Princess','Count','Countess','Old','Emperor','Mademoiselle'].includes(x)).slice(0,2).map(x=>x[0]).join('');
const pill=(s,cl='')=>`<span class="pill ${cl}">${esc(s)}</span>`;const empty=s=>`<div class="empty">${s}</div>`;
const cite=(id,p=0,label)=>`<button class="source" data-action="source" data-chapter="${id}" data-paragraph="${p}">${esc(label||`${chLabel(id)}, ¶${p+1}`)} ↗</button>`;
const charBtn=id=>character(id)&&character(id).first<=state.horizon?`<button class="pill" data-action="character" data-id="${id}">${esc(name(id))}</button>`:'';
const charSelect=(key='character',label='All characters')=>`<select data-filter="${key}" aria-label="Character"><option value="">${label}</option>${filters[key]&&character(filters[key])?.first>state.horizon?`<option value="${filters[key]}" selected>Selection not yet revealed</option>`:''}${unlockedChars().map(c=>`<option value="${c.id}" ${filters[key]===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`;
const placeSelect=()=>`<select data-filter="place" aria-label="Place"><option value="">All places</option>${unlockedPlaces().map(c=>`<option value="${c.id}" ${filters.place===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`;
const themeSelect=()=>`<select data-filter="theme" aria-label="Theme"><option value="">All themes</option>${Object.keys(I.themes).map(c=>`<option ${filters.theme===c?'selected':''}>${c}</option>`).join('')}</select>`;
const head=(k,title,desc,action='')=>`<header class="pagehead"><div><span class="eyebrow">${k}</span><h1>${title}</h1><p>${desc}</p></div>${action}</header>`;
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function render(){closePeek();state.chapter=Math.min(state.chapter,state.horizon);const c=chapter(state.horizon);$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brandmark">✳</div><div class="brand">War & Peace<span>A READING ATLAS</span></div><nav aria-label="Main navigation">${navs.map(([id,icon,title])=>`<button class="${state.view===id?'active':''}" data-view="${id}"><b>${icon}</b>${title}</button>`).join('')}</nav><div class="sidebottom"><span class="eyebrow">Your reading horizon</span><p style="margin-top:9px">${chLabel(state.horizon)}</p><div class="progressline"><span style="width:${state.horizon/365*100}%"></span></div><div class="splitlabel"><span>${state.horizon} / 365 chapters</span><span>${Math.round(state.horizon/365*100)}%</span></div><p style="margin-top:20px">Leo Tolstoy<br>Louise & Aylmer Maude</p><button class="textbutton" data-action="about">Edition & methods ↗</button></div></aside><main class="main"><div class="topbar"><form id="globalSearch"><input class="searchbox" aria-label="Search within reading horizon" placeholder="⌕  Search the revealed text…" name="search" autocomplete="off"></form><small>THE NOVEL, THROUGH MANY LENSES</small><button class="compact" data-action="note">+ Note</button></div><div class="boundary"><span class="shield">◈ &nbsp; SPOILER BOUNDARY · Through the end of this chapter</span><select id="horizonBook" aria-label="Reading boundary book">${T.books.map(b=>`<option value="${b.id}" ${b.id===c.book?'selected':''}>${b.id<16?'Book '+b.id:'Epilogue '+(b.id-15)}</option>`).join('')}</select><select id="horizonChapter" aria-label="Reading boundary chapter">${T.chapters.filter(x=>x.book===c.book).map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>Chapter ${x.roman}</option>`).join('')}</select><button class="compact" data-action="applyBoundary">Set horizon</button></div><div class="content" id="mainContent">${views[state.view]()}<footer class="footer"><span>WAR & PEACE / THE MAUDE READING ATLAS</span><span>Text-complete · Editorial layer selective · <button class="textbutton" data-action="about">Sources & methods</button></span></footer></div></main></div>`;bind();save();history.replaceState(null,'',state.view==='read'?`#read-${state.chapter}-${focusParagraph??0}`:'#'+state.view);if(focusParagraph!==null&&state.view==='read'){setTimeout(()=>{const p=$('#p'+focusParagraph);p?.classList.add('highlight');p?.scrollIntoView({behavior:'smooth',block:'center'});focusParagraph=null},50)}}
const compactNetwork=()=>typeof window!=='undefined'&&window.matchMedia('(max-width:760px)').matches;
function constellation(chars=unlockedChars().slice(0,8),large=false,edges=null){const mobile=compactNetwork(),w=mobile?380:large?850:450,h=mobile?(large?460:300):large?480:260,cx=w/2,cy=h/2,r=mobile?(large?150:95):large?170:86;const pts=chars.map((c,i)=>({c,x:cx+Math.cos(i/chars.length*Math.PI*2-Math.PI/2)*r*(mobile?(large?.90:1.35):1.5),y:cy+Math.sin(i/chars.length*Math.PI*2-Math.PI/2)*r}));let lines='';if(edges){for(const e of edges){const a=pts.find(p=>p.c.id===e.from),b=pts.find(p=>p.c.id===e.to);if(a&&b)lines+=`<g class="graph-edge" data-action="peek-edge" data-from="${e.from}" data-to="${e.to}" data-chapter="${e.chapter}" data-paragraph="${e.paragraph}" data-label="${esc(e.label)}" tabindex="0" role="button" aria-haspopup="dialog" aria-expanded="false" aria-label="Inspect ${esc(name(e.from))}: ${esc(e.label)}: ${esc(name(e.to))}"><line class="edge-hit" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><line class="graph-link" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/></g>`}}else lines='';return `<svg viewBox="0 0 ${w} ${h}" aria-label="${large?'Character relationship graph':'People revealed so far'}" role="group"><circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="#c5cdb9" stroke-dasharray="2 6"/><ellipse cx="${cx}" cy="${cy}" rx="${r*(mobile?(large?.90:1.35):1.5)}" ry="${r}" fill="none" stroke="#d3d9c8"/>${lines}${!large?`<circle cx="${cx}" cy="${cy}" r="32" fill="#f6f4e9" stroke="#b4c0a0"/><text x="${cx}" y="${cy+6}" text-anchor="middle" font-family="Georgia" font-size="20" fill="#4a6149">W & P</text>`:''}${pts.map(p=>`<g class="graph-node" data-action="peek-character" aria-haspopup="dialog" aria-expanded="false" data-id="${p.c.id}" role="button" tabindex="0" aria-label="Inspect ${esc(p.c.name)}"><circle class="node-hit" cx="${p.x}" cy="${p.y}" r="${mobile?26:large?30:20}" fill="transparent" stroke="none"/><circle cx="${p.x}" cy="${p.y}" r="${mobile?22:large?22:13}" fill="#f7f6ed" stroke="#8c9e78"/><text x="${p.x}" y="${p.y+4}" text-anchor="middle" font-size="${large?13:10}" fill="#4a6149">${initials(p.c.name)}</text><text x="${p.x}" y="${p.y+(large?41:29)}" text-anchor="${mobile&&p.x>cx+40?'end':mobile&&p.x<cx-40?'start':'middle'}" font-size="${mobile?11:large?12:9}" fill="#57684e">${esc(p.c.name)}</text></g>`).join('')}</svg>`}
function overview(){const c=chapter(state.horizon),active=I.characters.filter(x=>c.characters.includes(x.id)&&x.first<=state.horizon),ev=visibleEvents().filter(e=>e.chapter===c.id),ks=visibleKnowledge().filter(e=>e.chapter===c.id);return `<section class="hero"><div><span class="eyebrow">Leo Tolstoy · The Maude translation</span><h1>A world, revealed<br>one chapter at a time.</h1><p>Follow people, places, and the passage of knowledge. Change the lens; keep your place in the story.</p><div class="actions"><button class="primary" data-action="readCurrent">Open ${chLabel(c.id)} &nbsp; ↗</button><button data-view="query">Explore a connection</button></div></div><div class="heroart">${constellation(active.slice(0,8))}<div class="caption">Name index · positions imply no relationships</div></div></section><div class="stats"><div class="stat"><strong>${state.horizon}</strong><span>Chapters revealed</span></div><div class="stat"><strong>${unlockedChars().length}</strong><span>Indexed characters</span></div><div class="stat"><strong>${unlockedPlaces().length}</strong><span>Places mentioned</span></div><div class="stat"><strong>${visibleKnowledge().length}</strong><span>Disclosure records</span></div></div><div class="grid2"><section><div class="sectiontitle"><h2>At the reading horizon</h2><span class="eyebrow">${chLabel(c.id)}</span></div><div class="panel"><span class="eyebrow">The text</span><p class="quote">${esc(c.paragraphs.find(p=>!p.note).text.slice(0,330))}…</p>${cite(c.id,0,'Enter the chapter')}</div>${ev.slice(0,2).map(eventCard).join('')}<div class="spaced"><div class="sectiontitle"><h2>People in the text</h2><button class="textbutton" data-view="characters">All character cards ↗</button></div><div class="cards">${active.slice(0,4).map(charCard).join('')}</div><p class="coverage">Name matches include people discussed in their absence.</p></div></section><section><div class="sectiontitle"><h2>The shape of disclosure</h2><button class="textbutton" data-view="knowledge">Open ledger ↗</button></div><div class="panel"><span class="eyebrow">Reader / character</span><h3 style="margin:12px 0">Who has access to what?</h3><p style="font-size:12px;color:var(--muted)">A remark in company, an unread letter, a private thought. Follow the difference between information in the world and information available to its people.</p>${ks.slice(0,3).map(k=>`<div class="row"><span class="dot"></span><div><p style="font-size:12px">${esc(k.claim)}</p><small>${esc(name(k.holder))}${k.recipient?' → '+esc(name(k.recipient)):' · '+esc(k.mode)}</small><br>${cite(k.chapter,k.paragraph)}</div></div>`).join('')||'<p class="coverage">No curated disclosure record at this chapter. Browse the revealed ledger.</p>'}</div><div class="panel"><span class="eyebrow">Reading instruments</span>${[['timeline','⌁','One story, several clocks','Narrative sequence, historical year, and parallel threads.'],['atlas','◎','Place as a lens','Locate mentions and inspect the passages behind them.'],['query','⌕','Compose a question','Intersect people, places, themes, and exact language.']].map(([v,i,t,d])=>`<div class="row"><span class="bullet">${i}</span><div class="fill"><h3 style="font-size:21px">${t}</h3><small>${d}</small></div><button class="textbutton" data-view="${v}" aria-label="Open ${t}">↗</button></div>`).join('')}</div></section></div>`}
function charCard(c){const hits=mentions(c);return `<button class="card" data-action="character" data-id="${c.id}"><span class="avatar ${c.family}">${initials(c.name)}</span><h3>${esc(c.name)}</h3><p>${esc(c.family)} index · ${hits.length} chapter${hits.length===1?'':'s'}</p><small>First named: ${chLabel(c.first)} ↗</small></button>`}
function charactersView(){let cs=unlockedChars().filter(c=>(!filters.family||c.family===filters.family)&&(!filters.query||norm(c.name+' '+c.aliases.join(' ')).includes(norm(filters.query))));return head('The people','Characters & their many names','Cards gather textual occurrences, supported relationships, and disclosures up to your horizon.')+`<div class="filters"><input id="characterSearch" placeholder="Find a name or alias…" value="${esc(filters.query)}" aria-label="Filter character names"><select data-filter="family" aria-label="Family index"><option value="">All family / social indexes</option>${[...new Set(unlockedChars().map(c=>c.family))].map(f=>`<option ${filters.family===f?'selected':''}>${f}</option>`).join('')}</select><span class="muted">${cs.length} cards revealed</span></div><div class="cards">${cs.map(charCard).join('')}</div><p class="coverage">38 indexed characters across the full novel. Occurrences use explicit name patterns; pronouns are not resolved, and ambiguous names can produce false matches. Family/social indexes are finding aids, not claims of co-presence.</p>`}
function linkedText(text){let out='',pos=0;const candidates=[];for(const c of unlockedChars()){for(const alias of c.aliases){const regex=new RegExp('\\b'+alias.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','gi'),normalized=norm(text);let m;while((m=regex.exec(normalized))){if(c.id==='nikolai'&&normalized.slice(Math.max(0,m.index-7),m.index)==='prince ')continue;candidates.push({start:m.index,end:m.index+m[0].length,c});}}}candidates.sort((a,b)=>a.start-b.start||b.end-a.end);for(const m of candidates){if(m.start<pos)continue;out+=esc(text.slice(pos,m.start))+`<a class="entity" href="#character-${m.c.id}" data-action="character" data-id="${m.c.id}">${esc(text.slice(m.start,m.end))}</a>`;pos=m.end;}return out+esc(text.slice(pos));}
function readView(){const c=chapter(state.chapter),cs=I.characters.filter(x=>c.characters.includes(x.id)&&x.first<=state.horizon);return head('The primary source','The Maude text','Paragraph numbers are atlas locators. Original translation notes are retained inline.')+`<div class="actions"><button data-action="prev" ${c.id===1?'disabled':''}>← Previous</button><select id="readChapter" aria-label="Chapter to read">${T.chapters.filter(x=>x.id<=state.horizon).map(x=>`<option value="${x.id}" ${c.id===x.id?'selected':''}>${chLabel(x.id)}</option>`).join('')}</select><button data-action="next">${c.id===state.horizon?'Reveal next chapter →':'Next →'}</button><button class="textbutton" data-action="note">Annotate this chapter</button></div><div class="readerhead"><span class="eyebrow">${esc(T.books[c.book-1].title)}</span><h2>Chapter ${c.roman}</h2><small>${c.words.toLocaleString()} words · approximately ${Math.ceil(c.words/220)} minutes</small></div><div class="readergrid"><article class="reader">${c.paragraphs.map((p,i)=>`<p id="p${i}" class="${p.note?'note':''}"><button class="paranum" data-action="paragraph" data-paragraph="${i}" aria-label="Annotate paragraph ${i+1}">${i+1}</button>${p.note?'<small>MAUDE TEXT NOTE</small><br>':''}${linkedText(p.text)}</p>`).join('')}</article><aside class="readeraside"><div class="panel"><h3>Names in this chapter</h3>${cs.map(c=>charBtn(c.id)).join('')||'<small>No indexed names.</small>'}<p class="coverage">Mention does not establish presence.</p></div><div class="panel"><h3>Related entries</h3>${visibleEvents().filter(e=>e.chapter===c.id).map(e=>`<p>${esc(e.title)}</p>${cite(e.chapter,e.paragraph)}`).join('')||'<small>No curated event entry.</small>'}<h3>Place mentions</h3>${c.places.map(id=>`<button class="pill" data-action="place" data-id="${id}">${esc(placeName(id))}</button>`).join('')||'<small>No indexed place names.</small>'}<h3>Annotations</h3><small>${notes.filter(n=>n.chapter===c.id).length} saved locally</small><br><button class="textbutton" data-action="note">Add a reading note ↗</button></div></aside></div>`}
function eventCard(e){return `<div class="panel"><span class="eyebrow">${esc(e.thread)} · ${esc(e.year)}</span><h3 style="margin:10px 0">${esc(e.title)}</h3><p style="font-size:12px">${esc(e.summary)}</p>${cite(e.chapter,e.paragraph)}</div>`}
function timelineView(){let events=visibleEvents().filter(e=>(!filters.character||e.characters.includes(filters.character))&&(!filters.thread||e.thread===filters.thread)&&(!filters.place||e.place===filters.place));events.sort((a,b)=>filters.order==='story'?a.year-b.year||a.chapter-b.chapter:a.chapter-b.chapter);const groups={};for(const e of events){const key=filters.group==='book'?`Book ${chapter(e.chapter).book}`:filters.group==='year'?String(e.year):e.thread;(groups[key]??=[]).push(e)}return head('Sequence / simultaneity','Timelines, decomposed','Separate the order of telling from the approximate year of events. Expand each thread back into the text.')+`<div class="filters">${charSelect()}${placeSelect()}<label>Order<select data-filter="order"><option value="narrative" ${filters.order==='narrative'?'selected':''}>Narrative order</option><option value="story" ${filters.order==='story'?'selected':''}>Story year</option></select></label><label>Decompose by<select data-filter="group"><option value="thread" ${filters.group==='thread'?'selected':''}>Narrative thread</option><option value="book" ${filters.group==='book'?'selected':''}>Book</option><option value="year" ${filters.group==='year'?'selected':''}>Year</option></select></label><button class="textbutton" data-action="reset">Reset lenses</button></div><div class="panel timelinegrid"><span class="eyebrow">Parallel threads · position in the revealed text</span>${['Society','Family','War','Inner life','History'].map(t=>`<div class="lane"><span>${t}</span><div class="lanetrack">${events.filter(e=>e.thread===t).map(e=>`<button style="left:${Math.min(98,Math.max(2,(e.chapter-1)/Math.max(1,state.horizon-1)*100))}%" data-action="event" data-id="${e.id}" title="${esc(e.title)} — ${chLabel(e.chapter)}" aria-label="${esc(e.title)}"></button>`).join('')}</div></div>`).join('')}<div class="splitlabel"><span>Opening chapter</span><span>${chLabel(state.horizon)}</span></div></div><p class="coverage">${events.length} revealed editorial events. Years are broad story-time labels, not precise dating; dot positions always follow narrative order. The event index is selective.</p>${Object.entries(groups).map(([g,es])=>`<h2 class="grouphead">${esc(g)}</h2>${es.map(e=>`<div class="event"><div class="date">${esc(e.year)}<small>${chLabel(e.chapter)}</small></div><div><span class="eyebrow">${esc(e.thread)}${e.place?' / '+esc(placeName(e.place)):''}</span><h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p><div>${e.characters.map(charBtn).join('')}</div>${cite(e.chapter,e.paragraph)}</div></div>`).join('')}`).join('')||empty('No curated events intersect these lenses within the reading boundary.')}`}
function connectionsView(){filters.networkKind=filters.networkKind||filters.graph||'relations';return networkWorkspace()}
function mapSVG(){const box=filters.region==='central'?[10,46,21,52]:filters.region==='russia'?[23,49,42,62]:[-12,35,48,67];const xy=(lon,lat)=>[(lon-box[0])/(box[2]-box[0])*900,(box[3]-lat)/(box[3]-box[1])*510];const places=unlockedPlaces().filter(p=>p.kind!=='fictional');return `<svg viewBox="0 0 900 510" role="img" aria-label="Geographic map of revealed place mentions"><defs><clipPath id="mapclip"><rect width="900" height="510"/></clipPath></defs><rect class="water" width="900" height="510"/><g clip-path="url(#mapclip)">${G.map(f=>f.polygons.map(poly=>`<path class="geo" d="${poly.map((p,i)=>{const[x,y]=xy(...p);return(i?'L':'M')+x.toFixed(1)+','+y.toFixed(1)}).join('')}Z"/>`).join('')).join('')}${[40,50,60].map(lat=>`<line x1="0" y1="${xy(0,lat)[1]}" x2="900" y2="${xy(0,lat)[1]}" stroke="#c2d0c3" stroke-dasharray="3 6" opacity=".45"/>`).join('')}${places.map(p=>{let[x,y]=xy(p.lon,p.lat);const count=p.hits.filter(h=>h.chapter<=state.horizon).length;return `<g data-action="mapPlace" data-id="${p.id}" class="graph-node" tabindex="0" role="button" aria-label="${esc(p.name)}, ${count} chapters"><circle cx="${x}" cy="${y}" r="${filters.mapPlace===p.id?11:7}" fill="${filters.mapPlace===p.id?'#a85436':'#f8f7e9'}" stroke="#855d3c" stroke-width="1.5"/><circle cx="${x}" cy="${y}" r="2.5" fill="#855d3c"/><text opacity="${filters.mapPlace===p.id||['petersburg','moscow','smolensk','paris','kiev','vienna','vilna'].includes(p.id)||filters.region!=='europe'?1:0}" x="${x+12}" y="${y-9}" font-size="12" style="paint-order:stroke;stroke:#f0f2e8;stroke-width:3px">${esc(p.name)}</text><title>${esc(p.name)} · ${count} chapters</title></g>`}).join('')}</g><text x="25" y="32" font-size="10" letter-spacing="3">EUROPE / REFERENCE GEOGRAPHY</text><text x="864" y="40" font-size="18">N</text><path d="M870,48 L865,68 L875,68 Z" fill="#7c8b70"/></svg>`}
function atlasView(){const places=unlockedPlaces();let p=places.find(p=>p.id===filters.mapPlace);return head('The geography of the novel','An atlas of mentions','Where the text points, and what it says there. Select a place to move from geography back to evidence.')+`<div class="filters"><select data-filter="mapPlace" aria-label="Select map place"><option value="">Choose a revealed place</option>${places.map(p=>`<option value="${p.id}" ${filters.mapPlace===p.id?'selected':''}>${esc(p.name)}${p.kind==='fictional'?' · fictional estate':''}</option>`).join('')}</select>${charSelect()}<select data-filter="region" aria-label="Map region"><option value="europe" ${filters.region==='europe'?'selected':''}>Europe</option><option value="central" ${filters.region==='central'?'selected':''}>Central European theater</option><option value="russia" ${filters.region==='russia'?'selected':''}>Russian theater</option></select><button class="textbutton" data-action="reset">Reset lenses</button></div><div class="map-layout"><section><div class="svgpanel">${mapSVG()}</div><p class="mapcaption">Geographic reference with modern country outlines (Natural Earth, via datasets/geo-countries). Markers represent place-name mentions, not a character’s confirmed position or army routes. Fictional estates have no asserted coordinates.</p><div class="legend"><span>◉ Named place</span><span>○ Select to inspect</span></div><div class="actions">${places.filter(p=>p.kind==='fictional').map(p=>`<button class="pill" data-action="mapPlace" data-id="${p.id}">${esc(p.name)} · fictional estate</button>`).join('')}</div></section><aside class="panel"><span class="eyebrow">Place dossier</span><h2 style="margin:12px 0">${p?esc(p.name):'Follow a place'}</h2>${p?`<p class="coverage">${p.kind==='fictional'?'Fictional estate; not pinned to a speculative geographic location.':'Approximate reference point: '+p.lat.toFixed(2)+'° N, '+p.lon.toFixed(2)+'° E.'}</p><p>${p.hits.filter(h=>h.chapter<=state.horizon).length} chapters mention this place.</p>`:'<p class="muted">Choose a marker or a place in the menu. The map grows with your reading horizon.</p>'}</aside></div>${p?`<h2 class="grouphead">Passages ${filters.character?'with '+esc(name(filters.character)):''}</h2>${p.hits.filter(h=>h.chapter<=state.horizon&&(!filters.character||chapter(h.chapter).characters.includes(filters.character))).slice(0,60).map(h=>`<div class="result"><span class="eyebrow">${chLabel(h.chapter)}</span><p>${esc(chapter(h.chapter).paragraphs[h.paragraphs[0]].text.slice(0,350))}…</p>${cite(h.chapter,h.paragraphs[0])}</div>`).join('')||empty('No revealed chapters match this place and character.')}<p class="coverage">Up to 60 chapter hits shown. Character intersection is at chapter level.</p>`:''}`}
function knowledgeView(){const records=visibleKnowledge().filter(k=>(!filters.character||k.holder===filters.character||k.recipient===filters.character)&&(!filters.mode||k.mode===filters.mode));return head('Information has a history','Who knows? Who is told?','Track the character involved, the channel, and the reader reveal. Each record describes its cited moment, not a permanent knowledge state.')+`<div class="notice"><strong>Missing evidence ≠ ignorance.</strong> Records describe the cited passage; knowledge may change later in the same chapter. This is a selective ledger, not an omniscient model of every mind. A spoken claim establishes access to a claim, not its truth or the listener’s belief.</div><div class="filters">${charSelect()}<select data-filter="mode" aria-label="Disclosure channel"><option value="">All channels</option>${['told','witnessed','thought','narrated','letter'].map(m=>`<option ${filters.mode===m?'selected':''}>${m}</option>`).join('')}</select>${charSelect('comparison','Compare with…')}<button class="textbutton" data-action="reset">Reset lenses</button></div>${filters.character&&filters.comparison?knowledgeCompare(filters.character,filters.comparison):''}<div class="tablewrap"><table><thead><tr><th>Information disclosed</th><th>Character in record</th><th>Access / recipient</th><th>Reader learns</th></tr></thead><tbody>${records.map(k=>`<tr><td><p>${esc(k.claim)}</p><small>${esc(k.note||'')}</small><br><span class="tag">${esc(k.status)}</span></td><td>${k.holder==='reader'?'Narrator → reader':charBtn(k.holder)||esc(name(k.holder))}<br><small>${knowledgeRole(k)}</small></td><td>${pill(k.mode)}<br>${k.recipient?charBtn(k.recipient)||esc(name(k.recipient)):'<small>No recipient asserted</small>'}</td><td>${cite(k.chapter,k.paragraph)}</td></tr>`).join('')}</tbody></table></div>${records.length?'':empty('No curated disclosure records intersect these lenses.')}<p class="coverage">${records.length} records revealed for this lens; editorial coverage is selective. Every record has an explicit reader-disclosure chapter. Absent cells remain unknown.</p>`}
function knowledgeCompare(a,b){const ks=visibleKnowledge().filter(k=>[k.holder,k.recipient].some(id=>id===a||id===b));return `<div class="panel"><h3>${esc(name(a))} / ${esc(name(b))}</h3><p class="coverage">Recorded involvement in each disclosure, not a claim about total knowledge.</p><div class="tablewrap"><table><thead><tr><th>Disclosure</th><th>${esc(name(a))}</th><th>${esc(name(b))}</th></tr></thead><tbody>${ks.map(k=>`<tr><td>${esc(k.claim)}</td>${[a,b].map(id=>`<td>${k.holder===id?knowledgeRole(k):k.recipient===id?'Receives the claim':'Not established'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function queryView(){return head('Compose your lenses','The query lab','Intersect people, places, recurring language, and a chapter range. Results are always clipped to your reading horizon.')+`<form id="queryForm"><div class="querybar"><input id="queryInput" value="${esc(filters.query)}" placeholder='Try: "free will" or Pierre Napoleon' aria-label="Text query"><button class="primary">Run query ↗</button></div><div class="filters">${charSelect()}${placeSelect()}${themeSelect()}<label>From chapter (1–${state.horizon})<input id="queryFrom" type="number" min="1" max="${state.horizon}" value="1" style="width:130px;min-width:0"></label><label>Through chapter<input id="queryTo" type="number" min="1" max="${state.horizon}" value="${state.horizon}" style="width:130px;min-width:0"></label><button type="button" class="textbutton" data-action="reset">Reset lenses</button></div></form><div class="actions">${['love','money','war','faith','"free will"'].map(s=>`<button class="pill" data-action="preset" data-query="${esc(s)}">${esc(s)}</button>`).join('')}</div><p class="coverage">Case- and accent-insensitive text fragments use AND within a paragraph; quotation marks keep phrases together. Character and place lenses intersect at chapter level. Theme lenses use declared vocabulary, not semantic interpretation.</p><details><summary class="textbutton">Inspect the theme vocabularies</summary><p class="coverage">${Object.entries(I.themes).map(([k,v])=>`<strong>${k}</strong>: ${v.join(', ')}`).join('<br>')}</p></details><div id="queryResults">${queryResults()}</div>`}
function queryResults(from=1,to=state.horizon){const tokens=(norm(filters.query).match(/"[^"]+"|\S+/g)||[]).map(t=>t.replace(/^"|"$/g,''));let hits=[];let cs=T.chapters.filter(c=>c.id>=from&&c.id<=Math.min(to,state.horizon)&&(!filters.character||c.characters.includes(filters.character))&&(!filters.place||c.places.includes(filters.place))&&(!filters.theme||c.themes[filters.theme]>0));for(const c of cs){for(let i=0;i<c.paragraphs.length;i++){const p=c.paragraphs[i],n=norm(p.text);if(tokens.every(t=>n.includes(t))&&(!filters.theme||I.themes[filters.theme].some(w=>new RegExp('\\b'+w+'\\b').test(n))))hits.push({c,i,p})}}let counts={};hits.forEach(h=>counts[h.c.id]=(counts[h.c.id]||0)+1);return `<div class="sectiontitle spaced"><h2>${hits.length.toLocaleString()} passages <small>in ${Object.keys(counts).length} chapters</small></h2><button class="textbutton" data-action="exportQuery">Export matching passages ↓</button></div><div class="panel"><span class="eyebrow">Distribution through the revealed chapters</span><div class="spectrum" style="margin-top:15px">${T.chapters.filter(c=>c.id<=state.horizon).map(c=>`<button title="${chLabel(c.id)} · ${counts[c.id]||0} passages" aria-label="${chLabel(c.id)}, ${counts[c.id]||0} matches" style="height:${Math.max(3,(counts[c.id]||0)/Math.max(1,...Object.values(counts))*43)}px" data-action="source" data-chapter="${c.id}" data-paragraph="0"></button>`).join('')}</div></div>${hits.slice(0,80).map(({c,i,p})=>{let text=p.text;const n=norm(text);const idx=tokens.length?n.indexOf(tokens[0]):0;const start=Math.max(0,idx-90);let excerpt=(start?'…':'')+text.slice(start,start+500)+(text.length>start+500?'…':'');return `<div class="result"><span class="eyebrow">${chLabel(c.id)} · ¶${i+1}${p.note?' · translation note':''}</span><p>${esc(excerpt)}</p>${cite(c.id,i,'Read in context')} &nbsp; <button class="textbutton" data-action="annotateResult" data-chapter="${c.id}" data-paragraph="${i}">Annotate</button></div>`}).join('')||empty('No passages match this intersection within your reading boundary.')}<p class="coverage">Showing ${Math.min(80,hits.length)} of ${hits.length} matching passages. Narrow the lenses or export the full result.</p>`}
function notebookView(){const visible=notes.filter(n=>n.chapter<=state.horizon);return head('Marginalia','Your notebook','Notes and reading progress stay in this browser. Export a backup to carry them elsewhere.',`<button class="primary" data-action="note">+ Add note</button>`)+`<div class="actions"><button data-action="exportNotes">Export notes ↓</button><label><input type="file" id="importNotes" accept="application/json" style="display:none"><span class="pill" style="cursor:pointer">Import backup ↑</span></label></div><p class="coverage">${visible.length} visible notes. Notes attached beyond your current horizon remain hidden.</p>${visible.sort((a,b)=>a.chapter-b.chapter).map(n=>`<article class="notecard"><span class="eyebrow">${chLabel(n.chapter)}${n.paragraph!=null?' · ¶'+(n.paragraph+1):''}</span><p style="margin:12px 0">${esc(n.text)}</p>${cite(n.chapter,n.paragraph||0,'Return to passage')}<div class="actions"><button class="textbutton" data-action="editNote" data-id="${n.id}">Edit</button><button class="textbutton" data-action="deleteNote" data-id="${n.id}">Delete</button></div></article>`).join('')||empty('An empty margin is an invitation. Add a note, or tap a paragraph number in the text.')}`}
const views={overview,read:readView,characters:charactersView,connections:connectionsView,timeline:timelineView,atlas:atlasView,knowledge:knowledgeView,query:queryView,notebook:notebookView};
function openDrawer(html){closePeek();lastFocus=document.activeElement;$('#drawer').innerHTML=`<div class="backdrop" data-action="close"></div><section class="drawer" role="dialog" aria-modal="true" aria-label="Atlas detail"><button class="close" data-action="close" aria-label="Close detail">✕</button>${html}</section>`;document.body.style.overflow='hidden';$('.drawer .close').focus();bindDrawer()}
function closeDrawer(){ $('#drawer').innerHTML='';document.body.style.overflow='';lastFocus?.focus() }
function knowledgeRole(k){
 if(['k10','k12'].includes(k.id))return 'Explicitly unaware at this passage';
 if(k.id==='k20')return 'Mistaken belief at this passage';
 if(k.mode==='told')return 'Communicates the claim';
 if(k.mode==='witnessed')return 'Witnesses / perceives';
 if(k.mode==='thought')return 'Private experience';
 if(k.mode==='letter')return 'Reads the letter';
 return 'Subject of narrated report';
}

// Nonmodal inspection keeps the graph, horizon, lens, URL and scroll position intact.
let peek=null,peekTimer=null,peekRoot=null,suppressPeekFocus=false;
function peekCitation(ch,p){return `<button class="source" data-action="peekEvidence" data-chapter="${ch}" data-paragraph="${p}">${esc(chLabel(ch))}, ¶${p+1} · preview evidence</button>`}
function peekCharacterContent(id){
 const c=character(id);if(!c||c.first>state.horizon)return '';
 const hs=mentions(c),first=hs[0],rels=visibleRelations().filter(r=>r.from===id||r.to===id),ks=visibleKnowledge().filter(k=>k.holder===id||k.recipient===id);
 return `<span class="eyebrow">Character · through ${chLabel(state.horizon)}</span><h3 id="peek-title">${esc(c.name)}</h3><div>${c.aliases.filter(a=>a!==c.name).map(a=>pill(a)).join('')}</div><p class="peek-meta">${hs.length} chapter${hs.length===1?'':'s'} with name matches · not confirmed presence.</p><details><summary>First indexed passage</summary><p class="peek-quote">${esc(chapter(first.chapter).paragraphs[first.paragraphs[0]].text)}</p>${peekCitation(first.chapter,first.paragraphs[0])}</details><h4>Supported relationships <small>(${rels.length})</small></h4>${rels.slice(-2).map(r=>{const other=r.from===id?r.to:r.from;return `<div class="peek-record"><button class="textbutton" data-action="peekRelated" data-id="${other}">${esc(name(other))}</button><p>${esc(r.label)}</p>${peekCitation(r.chapter,r.paragraph)}</div>`}).join('')||'<p class="muted">No curated record within this horizon.</p>'}${rels.length>2?`<p class="peek-meta">Latest 2 of ${rels.length} records shown. These describe their cited moments.</p>`:''}<details><summary>Information records (${ks.length})</summary>${ks.slice(-1).map(k=>`<div class="peek-record"><span class="tag">${esc(k.holder===id?knowledgeRole(k):'Receives the claim')}</span><p>${esc(k.claim)}</p>${peekCitation(k.chapter,k.paragraph)}</div>`).join('')||'<p class="muted">No curated record. Knowledge is not established by a name match.</p>'}</details><details><summary>All indexed chapter links (${hs.length})</summary><div class="actions">${hs.map(h=>peekCitation(h.chapter,h.paragraphs[0])).join('')}</div></details><p class="peek-meta">Inspecting this card never changes your reading horizon.</p>`;
}
function peekEdgeContent(d){
 if(Number(d.chapter)>state.horizon)return '';
 return `<span class="eyebrow">${filters.graph==='mentions'?'Co-occurrence signal':'Historical relationship record'}</span><h3 id="peek-title">${esc(name(d.from))} & ${esc(name(d.to))}</h3><p>${esc(d.label)}</p>${peekCitation(Number(d.chapter),Number(d.paragraph))}<p class="peek-meta">${filters.graph==='mentions'?'Both indexed names occur in the chapter. This does not establish a meeting or shared knowledge.':'This assertion belongs to its cited moment. It is not necessarily the relationship at the end of your reading horizon.'}</p><div class="actions"><button class="pill" data-action="peekRelated" data-id="${d.from}">${esc(name(d.from))}</button><button class="pill" data-action="peekRelated" data-id="${d.to}">${esc(name(d.to))}</button></div>`;
}
function ensurePeekRoot(){
 if(peekRoot)return peekRoot;
 peekRoot=document.createElement('section');peekRoot.className='node-popover';peekRoot.id='node-popover';peekRoot.hidden=true;peekRoot.setAttribute('role','dialog');peekRoot.setAttribute('aria-modal','false');peekRoot.setAttribute('aria-labelledby','peek-title');document.body.appendChild(peekRoot);
 peekRoot.onclick=sharedClick;peekRoot.addEventListener('toggle',()=>{if(peek)placePeek()},true);
 peekRoot.onpointerenter=()=>clearTimeout(peekTimer);
 peekRoot.onpointerleave=()=>schedulePeekClose();
 peekRoot.onfocusin=()=>{clearTimeout(peekTimer);if(peek)peek.pinned=true};
 peekRoot.onfocusout=()=>setTimeout(()=>{if(peek&&!peek.pinned&&!peekRoot.contains(document.activeElement))closePeek()},0);
 return peekRoot;
}
function placePeek(){
 if(!peek||!peek.anchor.isConnected)return closePeek();
 const rect=peek.anchor.getBoundingClientRect(),pad=12;
 const w=window.innerWidth,h=window.innerHeight;
 if(compactNetwork()){
  const above=Math.max(0,rect.top-pad-10),below=Math.max(0,h-rect.bottom-pad-10),under=below>=Math.min(320,above);
  peekRoot.style.maxHeight=Math.max(160,Math.min(420,under?below:above))+'px';
  const box=peekRoot.getBoundingClientRect();
  peekRoot.style.left=Math.max(pad,Math.min(rect.left,w-box.width-pad))+'px';
  peekRoot.style.top=Math.max(pad,Math.min(under?rect.bottom+10:rect.top-box.height-10,h-box.height-pad))+'px';return;
 }
 peekRoot.style.maxHeight='';const box=peekRoot.getBoundingClientRect();
 let left=rect.right+12;if(left+box.width>w-pad)left=rect.left-box.width-12;
 let top=rect.top-16;
 left=Math.max(pad,Math.min(left,w-box.width-pad));top=Math.max(pad,Math.min(top,h-box.height-pad));
 peekRoot.style.left=left+'px';peekRoot.style.top=top+'px';
}
function paintPeek(html){
 const root=ensurePeekRoot();root.hidden=false;root.innerHTML=`<div class="peek-top"><small>${peek.pinned?'Tap outside to close · Esc on keyboard':'Preview · click the node to keep open'}</small><button data-action="closePeek" aria-label="Close node preview">×</button></div><div class="peek-content">${html}</div>`;placePeek();
}
function showPeek(anchor,pinned=false){
 clearTimeout(peekTimer);if(peek?.pinned&&!pinned&&peek.anchor!==anchor)return;
 if(peek?.anchor===anchor){if(pinned){peek.pinned=true;paintPeek(peek.html)}return;}
 closePeek();const html=anchor.dataset.action==='peek-edge'?peekEdgeContent(anchor.dataset):peekCharacterContent(anchor.dataset.id);if(!html)return;
 peek={anchor,pinned,html};anchor.setAttribute('aria-expanded','true');anchor.setAttribute('aria-controls','node-popover');paintPeek(html);
}
function togglePeek(anchor){if(peek?.anchor===anchor&&peek.pinned){closePeek();return;}showPeek(anchor,true);}
function showRelatedPeek(id){if(!peek)return;const html=peekCharacterContent(id);if(!html)return;peek.pinned=true;peek.html=html;paintPeek(html);}
function peekEvidence(ch,p){
 if(!peek||ch>state.horizon||!chapter(ch)?.paragraphs[p])return;
 peek.pinned=true;paintPeek(`<span class="eyebrow">Maude text · evidence</span><h3 id="peek-title">${chLabel(ch)}, ¶${p+1}</h3><p class="peek-quote">${esc(chapter(ch).paragraphs[p].text)}</p><div class="actions"><button class="compact" data-action="peekBack">← Back to card</button><button class="compact" data-action="source" data-chapter="${ch}" data-paragraph="${p}">Open full reader ↗</button></div>`);
}
function restorePeek(){if(peek)paintPeek(peek.html)}
function schedulePeekClose(){clearTimeout(peekTimer);peekTimer=setTimeout(()=>{if(peek&&!peek.pinned&&!peekRoot?.matches(':hover')&&!peekRoot?.contains(document.activeElement))closePeek()},250)}
function closePeek(restoreFocus=false){clearTimeout(peekTimer);if(!peek)return;const anchor=peek.anchor;anchor.setAttribute('aria-expanded','false');anchor.removeAttribute('aria-controls');peek=null;if(peekRoot){peekRoot.hidden=true;peekRoot.innerHTML=''}if(restoreFocus&&anchor.isConnected){suppressPeekFocus=true;anchor.focus();suppressPeekFocus=false;}}
function bindPeekTargets(){
 document.querySelectorAll('[data-action="peek-character"],[data-action="peek-edge"]').forEach(node=>{
  node.onpointerenter=e=>{if(e.pointerType==='mouse'&&!compactNetwork())showPeek(node)};
  node.onpointerleave=schedulePeekClose;
  node.onfocus=()=>{if(!peek&&!suppressPeekFocus&&node.matches(':focus-visible'))showPeek(node)};
  node.onblur=()=>setTimeout(()=>{if(peek&&!peek.pinned&&!peekRoot?.contains(document.activeElement))closePeek()},0);
 });
}
document.addEventListener('pointerdown',e=>{if(peek&&!e.target.closest('.node-popover,[data-action="peek-character"],[data-action="peek-edge"]'))closePeek()});
document.addEventListener('scroll',()=>{if(peek)placePeek()},true);
if(typeof window!=='undefined')window.addEventListener('resize',()=>{if(peek)placePeek()});
function characterDetail(id){const c=character(id);if(!c||c.first>state.horizon)return;const hs=mentions(c),h=hs[0],p=chapter(h.chapter).paragraphs[h.paragraphs[0]],rels=visibleRelations().filter(r=>r.from===id||r.to===id),ks=visibleKnowledge().filter(k=>k.holder===id||k.recipient===id);openDrawer(`<span class="eyebrow">Character dossier / ${esc(c.family)}</span><h2>${esc(c.name)}</h2><div>${c.aliases.map(a=>pill(a)).join('')}</div><p class="coverage">${hs.length} revealed chapters · ${hs.reduce((s,h)=>s+h.count,0)} name matches</p><div class="actions"><button class="primary" data-action="pivot" data-id="${id}" data-target="query">Query this character</button><button data-action="pivot" data-id="${id}" data-target="knowledge">Disclosure lens</button></div><h3>First indexed mention</h3><p class="quote">${esc(p.text)}</p>${cite(h.chapter,h.paragraphs[0])}<h3>Revealed relationships</h3>${rels.map(r=>`<div class="row"><div>${charBtn(r.from)} <small>${esc(r.label)}</small> ${charBtn(r.to)}<br>${cite(r.chapter,r.paragraph)}</div></div>`).join('')||'<p class="muted">No curated relationship yet.</p>'}<h3>Disclosure records</h3>${ks.map(k=>`<div class="row"><div><p>${esc(k.claim)}</p>${pill(k.mode)}${cite(k.chapter,k.paragraph)}</div></div>`).join('')||'<p class="muted">No disclosure record yet. This does not imply ignorance.</p>'}<h3>Occurrence trail</h3><div class="actions">${hs.map(h=>cite(h.chapter,h.paragraphs[0])).join('')}</div><p class="coverage">Alias matching is a finding aid. It includes reported mentions and can miss pronouns or alternative names.</p>`)}
function noteDrawer(ch=state.view==='read'?state.chapter:state.horizon,p=null,id=null){const n=id?notes.find(x=>x.id===id):null;if(n){ch=n.chapter;p=n.paragraph}if(ch>state.horizon)return;openDrawer(`<span class="eyebrow">Your marginalia</span><h2>${n?'Edit annotation':'Leave a trace'}</h2><p class="muted">${chLabel(ch)}${p!=null?' · paragraph '+(p+1):''}</p>${p!=null?`<p class="quote">${esc(chapter(ch).paragraphs[p]?.text.slice(0,330))}…</p>`:''}<form id="noteForm" data-chapter="${ch}" data-paragraph="${p??''}" data-id="${id??''}"><label for="noteText" class="coverage">Reading note</label><textarea id="noteText" required placeholder="A connection, a doubt, a pattern…">${esc(n?.text||'')}</textarea><div class="actions spaced"><button class="primary">Save note</button><button type="button" data-action="close">Cancel</button></div></form><p class="coverage">Saved in this browser. Use Notebook → Export notes for a portable backup.</p>`)}
function about(){openDrawer(`<span class="eyebrow">Edition / provenance / limits</span><h2>A text, not a black box.</h2><p>The complete <em>War and Peace</em>, translated by Louise and Aylmer Maude, is drawn from Project Gutenberg ebook 2600. All 365 chapters, 15 books and two epilogues are included. The source’s in-text footnotes are retained; paragraph numbers are atlas-specific.</p><h3>What is indexed</h3><p>38 character finding aids, 18 places, and nine keyword themes cover the text. Events, relationships, and disclosure records are selective editorial interpretations with paragraph-level source links. Their coverage is not exhaustive.</p><h3>Reading boundaries</h3><p>The horizon includes the <strong>end</strong> of the selected chapter. Text search, cards, edges, maps, notes, and disclosures are clipped to that boundary. The full text is downloaded to your browser, so this is a reading aid, not a security boundary. Linked external sources show the whole book.</p><h3>Knowledge is not a keyword</h3><p>Name matches do not establish co-presence. Sharing a chapter does not establish a meeting. Being told a claim does not establish belief or truth. The disclosure ledger records explicit access and labels interpretations; absent records mean “not established.”</p><h3>Time & geography</h3><p>Story years are approximate editorial labels. Narrative order uses Maude book/chapter order. The map uses modern reference outlines from Natural Earth through datasets/geo-countries; it does not depict 1805 borders. Fictional estates are deliberately unpinned.</p><h3>Edition crosswalk</h3><p>Gutenberg’s Books 1–3 correspond to Volume I; 4–8 to Volume II; 9–11 to Volume III; 12–15 to Volume IV. The two epilogue parts follow. Revised Maude editions may differ in wording or notes.</p><h3>Source links</h3><p><a href="${T.source}" target="_blank" rel="noopener">Maude text · Project Gutenberg ↗</a><br><a href="https://www.gutenberg.org/ebooks/2600" target="_blank" rel="noopener">Edition record & license ↗</a><br><a href="https://github.com/datasets/geo-countries" target="_blank" rel="noopener">Geographic outlines & attribution ↗</a></p><p class="coverage">Original text is public domain in the United States. Editorial annotations are newly written. No modern critical-edition notes have been copied.</p>`)}
function navigate(v){if(!views[v])return;closePeek();closeDrawer();state.view=v;filters.query='';render();window.scrollTo(0,0)}
function setHorizon(n){state.horizon=Math.max(1,Math.min(365,Number(n)));state.chapter=Math.min(state.chapter,state.horizon);filters.character=unlockedChars().some(c=>c.id===filters.character)?filters.character:'';filters.comparison=unlockedChars().some(c=>c.id===filters.comparison)?filters.comparison:'';filters.place=unlockedPlaces().some(p=>p.id===filters.place)?filters.place:'';filters.mapPlace=unlockedPlaces().some(p=>p.id===filters.mapPlace)?filters.mapPlace:'';closeDrawer();render();toast('Reading horizon: '+chLabel(state.horizon))}
function source(ch,p){if(ch>state.horizon){toast('This passage is beyond your reading horizon.');return}closeDrawer();state.chapter=ch;state.view='read';focusParagraph=p;history.replaceState(null,'',`#read-${ch}-${p}`);render()}
function download(filename,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function action(el){const a=el.dataset.action,id=el.dataset.id,ch=Number(el.dataset.chapter),p=Number(el.dataset.paragraph);if(a==='close')closeDrawer();else if(a==='about')about();else if(a==='peek-character'||a==='peek-edge')togglePeek(el);else if(a==='closePeek')closePeek(true);else if(a==='peekRelated')showRelatedPeek(id);else if(a==='peekEvidence')peekEvidence(ch,p);else if(a==='peekBack')restorePeek();else if(a==='character')characterDetail(id);else if(a==='source')source(ch,p);else if(a==='readCurrent'){state.chapter=state.horizon;navigate('read')}else if(a==='applyBoundary')setHorizon($('#horizonChapter').value);else if(a==='prev'){state.chapter=Math.max(1,state.chapter-1);render();window.scrollTo(0,0)}else if(a==='next'){if(state.chapter===365)return;state.chapter++;state.horizon=Math.max(state.horizon,state.chapter);render();window.scrollTo(0,0)}else if(a==='note')noteDrawer();else if(a==='paragraph')noteDrawer(state.chapter,p);else if(a==='annotateResult')noteDrawer(ch,p);else if(a==='editNote')noteDrawer(null,null,id);else if(a==='deleteNote'){notes=notes.filter(n=>n.id!==id);save();render();toast('Note deleted')}else if(a==='exportNotes')download('war-and-peace-notes.json',{version:1,notes,horizon:state.horizon});else if(a==='pivot'){filters.character=id;closeDrawer();state.view=el.dataset.target;filters.query='';render();window.scrollTo(0,0)}else if(a==='reset'){for(const k of ['character','place','theme','family','thread','mode','query','comparison','mapPlace'])filters[k]='';render()}else if(a==='place'){filters.mapPlace=id;navigate('atlas')}else if(a==='mapPlace'){filters.mapPlace=id;render()}else if(a==='event'){const e=visibleEvents().find(e=>e.id===id);if(e)openDrawer(`<span class="eyebrow">${esc(e.thread)} · ${e.year}</span><h2>${esc(e.title)}</h2><p>${esc(e.summary)}</p><div class="spaced">${e.characters.map(charBtn).join('')}</div><p class="quote">${esc(chapter(e.chapter).paragraphs[e.paragraph].text)}</p>${cite(e.chapter,e.paragraph)}`)}else if(a==='preset'){filters.query=el.dataset.query;render()}else if(a==='exportQuery'){const tokens=(norm(filters.query).match(/"[^"]+"|\S+/g)||[]).map(t=>t.replace(/^"|"$/g,''));const from=Number($('#queryFrom')?.value||1),to=Math.min(state.horizon,Number($('#queryTo')?.value||state.horizon));let results=[];for(const c of T.chapters.filter(c=>c.id>=from&&c.id<=to&&(!filters.character||c.characters.includes(filters.character))&&(!filters.place||c.places.includes(filters.place))))c.paragraphs.forEach((p,i)=>{if(tokens.every(t=>norm(p.text).includes(t))&&(!filters.theme||I.themes[filters.theme].some(w=>new RegExp('\\b'+w+'\\b').test(norm(p.text)))))results.push({chapter:c.id,label:chLabel(c.id),paragraph:i+1,text:p.text,source:T.source+'#'+c.anchor})});download('war-and-peace-query.json',{horizon:state.horizon,filters,from,to,results})}}
function sharedClick(e){const el=e.target.closest('[data-action],[data-view]');if(!el)return;e.preventDefault();if(el.dataset.view)navigate(el.dataset.view);else action(el)}
function bind(){bindPeekTargets();$('#app').onclick=sharedClick;$('#app').onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[data-action]')){e.preventDefault();action(e.target);if(peek?.pinned)peekRoot.querySelector('button')?.focus()}};$('#horizonBook').onchange=e=>{const book=Number(e.target.value);$('#horizonChapter').innerHTML=T.chapters.filter(c=>c.book===book).map(c=>`<option value="${c.id}">Chapter ${c.roman}</option>`).join('')};document.querySelectorAll('[data-filter]').forEach(el=>el.onchange=()=>{filters[el.dataset.filter]=el.value;render()});$('#globalSearch').onsubmit=e=>{e.preventDefault();filters.query=e.target.search.value;state.view='query';render()};if($('#readChapter'))$('#readChapter').onchange=e=>{state.chapter=Number(e.target.value);render()};if($('#characterSearch'))$('#characterSearch').oninput=e=>{const v=e.target.value,start=e.target.selectionStart;filters.query=v;render();$('#characterSearch').focus();$('#characterSearch').setSelectionRange(start,start)};if($('#queryInput'))$('#queryInput').oninput=e=>{filters.query=e.target.value};if($('#queryForm'))$('#queryForm').onsubmit=e=>{e.preventDefault();filters.query=$('#queryInput').value;const from=Math.max(1,Number($('#queryFrom').value)),to=Math.min(state.horizon,Number($('#queryTo').value));$('#queryResults').innerHTML=queryResults(from,to)};if($('#importNotes'))$('#importNotes').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.notes)||!data.notes.every(n=>typeof n.text==='string'&&Number.isInteger(n.chapter)&&n.chapter>=1&&n.chapter<=365&&(n.paragraph==null||(Number.isInteger(n.paragraph)&&n.paragraph>=0&&n.paragraph<chapter(n.chapter).paragraphs.length))))throw Error('format');for(const n of data.notes){const safe={id:typeof n.id==='string'&&/^[a-f0-9-]{36}$/.test(n.id)?n.id:uid(),text:n.text,chapter:n.chapter,paragraph:n.paragraph??null};if(!notes.some(x=>x.id===safe.id))notes.push(safe)}save();render();toast('Notes imported; reading boundary preserved.')}catch{toast('Could not import: choose a valid atlas notes backup.')}}}
function bindDrawer(){ $('#drawer').onclick=sharedClick;const form=$('#noteForm');if(form)form.onsubmit=e=>{e.preventDefault();const text=$('#noteText').value.trim();if(!text)return;const id=form.dataset.id||uid(),n={id,chapter:Number(form.dataset.chapter),paragraph:form.dataset.paragraph===''?null:Number(form.dataset.paragraph),text};const i=notes.findIndex(x=>x.id===id);if(i<0)notes.push(n);else notes[i]=n;save();closeDrawer();render();toast('Note saved')};}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closePeek(true);closeDrawer();}if(e.key==='Tab'&&$('.drawer')){const els=[...$('.drawer').querySelectorAll('button,a,input,select,textarea,[tabindex="0"]')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
installWorkspace();
installChapterAtlas();
Promise.all(['text','index','editorial','geography','locations','settings'].map(n=>fetch(n+'.json').then(r=>{if(!r.ok)throw Error(n);return r.json()}))).then(([t,i,e,g,l,a])=>{T=t;I=i;E=e;G=g;L=l;A=a;for(const p of L.places||[]){if(!I.places.some(q=>q.id===p.id))I.places.push({...p,first:Math.min(...L.observations.filter(o=>o.place===p.id).map(o=>o.chapter)),hits:[],aliases:[]})}state.horizon=Math.max(1,Math.min(365,Number(state.horizon)||1));state.chapter=Math.max(1,Math.min(state.horizon,Number(state.chapter)||1));if(!views[state.view])state.view='overview';if(views[location.hash.slice(1)])state.view=location.hash.slice(1)==='overview'?'connections':location.hash.slice(1);const m=location.hash.match(/^#read-(\d+)-(\d+)$/);if(m&&+m[1]<=state.horizon&&+m[1]>0){state.chapter=+m[1];state.view='read';focusParagraph=+m[2]}render()}).catch(e=>{$('#app').innerHTML='<div class="loading"><h2>The atlas could not load.</h2><p>Please refresh to try again.</p></div>';console.error(e)});
